mapper.sql:
FROM members m
LEFT JOIN members_info info ON m.company_id = info.company_id AND m.user_id = info.user_id

	LEFT JOIN members_rel_shop shop ON shop.user_id = m.user_id AND shop.company_id = m.company_id


	LEFT JOIN wxshops s ON shop.shop_id = s.wx_shop_id


	LEFT JOIN distribution_distributor d ON shop.shop_id = d.distributor_id


	LEFT JOIN members_rel_tags reltags ON reltags.user_id = m.user_id AND reltags.company_id = m.company_id


	LEFT JOIN point_member pm ON pm.user_id = m.user_id AND pm.company_id = m.company_id

WHERE m.company_id = #{f.companyId}

	AND m.grade_id = #{f.membersGradeId}


	AND m.user_id IN
	#{uid}


	AND m.user_id NOT IN
	#{uid}


	AND m.mobile = #{f.mobileEqEncrypted}


	AND m.remarks LIKE CONCAT('%', #{f.remarksLike}, '%')


	AND m.inviter_id = #{f.inviterId}


	AND m.user_card_code = #{f.userCardCode}


	AND info.username = #{f.usernameEqEncrypted}


	AND info.name = #{f.nameEq}


	AND m.created >= #{f.createdGte}


	AND m.created <= #{f.createdLte}


	AND info.birthday >= #{f.birthdayGte}


	AND info.birthday <= #{f.birthdayLte}


	AND info.have_consume = #{f.haveConsume}


	AND shop.shop_type = 'distributor'
	AND shop.shop_id IN
	#{did}


	AND shop.shop_type = 'shop'
	AND shop.shop_id IN
	#{sid}


	AND reltags.tag_id IN
	#{tid}


	AND pm.point = #{f.pointEq}


	AND pm.point >= #{f.pointGte}


	AND pm.point <= #{f.pointLte}

mapper.select:
SELECT DISTINCT m.user_id

ORDER BY m.user_id DESC
LIMIT #{limit} OFFSET #{offset}
